Dataspatium.assets.register("presets/api/lantmateriet-direkt.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"lantmateriet-direkt\",\n  \"name\": \"Lantmäteriet Direkt (Ortnamn)\",\n  \"publisher\": \"Lantmäteriet\",\n  \"description\": \"Sök ortnamn via Ortnamn Direkt. Kräver ett kostnadsfritt konto i Lantmäteriets Geotorget med API-nycklar för öppna data; token hämtas med dina nycklar direkt från webbläsaren.\",\n  \"docs\": \"https://www.lantmateriet.se/sv/geodata/vara-produkter/produktlista/ortnamn-direkt/\",\n  \"license\": { \"name\": \"CC0 1.0\", \"url\": \"https://creativecommons.org/publicdomain/zero/1.0/\" },\n  \"level\": 2,\n  \"baseUrl\": \"https://api.lantmateriet.se/distribution/produkter\",\n  \"auth\": {\n    \"type\": \"oauth2_client_credentials\",\n    \"tokenUrl\": \"https://api.lantmateriet.se/token\",\n    \"help\": \"Skapa ett konto i Geotorget, lägg till produkten Ortnamn Direkt (öppna data) och skapa API-nycklar. Klient-id (consumer key) och klienthemlighet (consumer secret) anges här.\",\n    \"signupUrl\": \"https://geotorget.lantmateriet.se/\"\n  },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 1 },\n  \"endpoints\": [\n    {\n      \"id\": \"ortnamn-fritext\",\n      \"name\": \"Sök ortnamn (fritext)\",\n      \"method\": \"GET\",\n      \"path\": \"/ortnamn/v2.1/referens/fritext/{text}\",\n      \"params\": [\n        { \"name\": \"text\", \"in\": \"path\", \"label\": \"Söktext\", \"type\": \"string\", \"required\": true, \"example\": \"Uppsala\" }\n      ],\n      \"response\": { \"format\": \"json\" },\n      \"dataset\": { \"name\": \"Ortnamn: {text}\" }\n    }\n  ],\n  \"notes\": \"Svaret är en lista med ortnamnsreferenser. Fler Direkt-tjänster (belägenhetsadress, fastighet) kan läggas till som egna konfigurationer med samma autentisering.\"\n}\n");
